/* Version is generated by scripts/prepare-pages.cjs from the complete app shell. */
const VERSION = '2a602359f3e0de34';
const BASE = new URL(self.registration.scope);
const PREFIX = `loop-shell:${encodeURIComponent(BASE.pathname)}:`;
const CACHE = PREFIX + VERSION;
const ASSETS = ['./', 'index.html', 'privacy.html', 'app.js', 'styles.css', 'growth.js', 'growth.css', 'manifest.webmanifest', 'icon.svg', 'icon-192.png', 'icon-512.png', 'icon-maskable-512.png', 'social-preview.png'];
const URLS = ASSETS.map(asset => new URL(asset, BASE).href);
const ALLOWED = new Set(URLS);
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    try {
      const cache = await caches.open(CACHE);
      await cache.addAll(URLS.map(url => new Request(url, {cache:'reload'})));
    } catch (error) { await caches.delete(CACHE); throw error; }
    // Updates wait until tabs close or the player explicitly chooses Update and reload.
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});
self.addEventListener('message', event => { if (event.data?.type === 'SKIP_WAITING') event.waitUntil(self.skipWaiting()); });
self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== BASE.origin || !url.pathname.startsWith(BASE.pathname)) return;
  url.search = ''; url.hash = '';
  // Cache only this version's explicit public shell. Never capture other projects or APIs.
  if (!ALLOWED.has(url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(url.href);
    if (cached) return cached;
    try { return await fetch(request); }
    catch { return new Response('Loop could not load this file offline. Reconnect and reload once.', {status:503, headers:{'Content-Type':'text/plain; charset=utf-8'}}); }
  })());
});
